type Matrix<T> = Vec<Vec<T>>;

fn broadcast(a: Vec<i8>, shape: Vec<u8>) -> Matrix<i8> {
    // Extract R and C from shape
    let r = shape[0] as usize;
    let c = shape[1] as usize;

    // Check broadcasting dimension
    if a.len() == r {
        // Broadcast as column vector: each row i filled with a[i]
        let mut matrix = Vec::with_capacity(r);
        for &val in &a {
            // Repeat val c times for this row
            let row = vec![val; c];
            matrix.push(row);
        }
        matrix
    } else {
        // Else a.len() == c, broadcast as row vector: duplicate a for each row
        let mut matrix = Vec::with_capacity(r);
        for _ in 0..r {
            matrix.push(a.clone());
        }
        matrix
    }
}